/* Workflow Studio POC. Browser-only, fictional data, zero network requests. */
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], clone=v=>JSON.parse(JSON.stringify(v));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const TYPES={trigger:{name:'Trigger',icon:'ϟ',description:'Start a process'},approval:{name:'Approval',icon:'♧',description:'Ask the right person'},condition:{name:'Condition',icon:'◇',description:'Choose the next path'},email:{name:'Send email',icon:'✉',description:'Keep people informed'},task:{name:'Create task',icon:'✓',description:'Make work happen'},wait:{name:'Wait',icon:'◷',description:'Pause before continuing'},state:{name:'Change state',icon:'↗',description:'Move the record forward'},webhook:{name:'Integration',icon:'⇄',description:'Call a connected service'}};
const PEOPLE=['Their manager','HR partner','Finance approver','IT team','Employee','System'];
const icons=type=>`<span class="block-icon type-${type}">${TYPES[type].icon}</span>`;
const select=(name,values,value,attrs='')=>`<select ${attrs} name="${name}">${values.map(v=>{let [key,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(key)}" ${String(key)===String(value)?'selected':''}>${esc(label)}</option>`}).join('')}</select>`;
const field=(label,content,hint='')=>`<label class="field"><span>${label}</span>${content}${hint?`<small>${hint}</small>`:''}</label>`;
const input=(name,value,type='text',attrs='')=>`<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>`;
const initialNode=(id,type,title,stage,extra={})=>({id,type,title,stage,owner:type==='trigger'?'Employee':type==='approval'?'Their manager':type==='task'?'HR partner':'System',due:2,delegate:true,independent:true,recipient:'Employee',body:'Your request has progressed. View the latest update in Payobook.',field:'amount',op:'gt',value:1000,hours:24,state:'Approved',...extra});
const TEMPLATES={expense:{name:'Expense reimbursement',domain:'Expenses',icon:'↗',model:'hr.expense',desc:'A smarter approval path, from claim to confirmation.',event:'Claim submitted',numeric:'Claim amount',unit:'AUD',value:2400,stages:[{name:'Submit',state:'Submitted'},{name:'Review',state:'Pending approval'},{name:'Complete',state:'Approved'}],nodes:[initialNode('trigger','trigger','Claim submitted',0),initialNode('manager','approval','Manager approval',1),initialNode('rule','condition','An extra check?',1),initialNode('finance','approval','Finance approval',1,{owner:'Finance approver'}),initialNode('finish','state','Approve the claim',2),initialNode('email','email','Let the employee know',2)]},leave:{name:'Time-off request',domain:'Time & attendance',icon:'☀',model:'hr.leave',desc:'Keep leave simple, with cover when a manager is away.',event:'Leave requested',numeric:'Days requested',unit:'days',value:7,stages:[{name:'Request',state:'To approve'},{name:'Review',state:'Second approval'},{name:'Complete',state:'Approved'}],nodes:[initialNode('trigger','trigger','Leave requested',0),initialNode('manager','approval','Manager approval',1),initialNode('rule','condition','More than five days?',1,{value:5}),initialNode('hr','approval','HR review',1,{owner:'HR partner'}),initialNode('finish','state','Approve time off',2),initialNode('email','email','Send the confirmation',2)]},onboarding:{name:'New hire onboarding',domain:'People',icon:'✧',model:'hr.employee',desc:'Bring HR, IT and the new starter into one shared journey.',event:'Offer accepted',numeric:'Equipment budget',unit:'AUD',value:1500,stages:[{name:'Welcome',state:'Offer accepted'},{name:'Prepare',state:'Preparing'},{name:'Ready',state:'Onboarded'}],nodes:[initialNode('trigger','trigger','Offer accepted',0),initialNode('email1','email','Send a warm welcome',0),initialNode('manager','task','Prepare employment pack',1,{owner:'HR partner'}),initialNode('it','task','Provision equipment',1,{owner:'IT team'}),initialNode('wait','wait','Wait for start day',1,{hours:48}),initialNode('finish','state','Mark onboarding complete',2,{state:'Onboarded'}),initialNode('email','email','Share the day-one guide',2)]},hiring:{name:'Candidate to offer',domain:'Talent acquisition',icon:'◎',model:'hr.applicant',desc:'Structured interviews, consistent decisions and a personal touch.',event:'Candidate shortlisted',numeric:'Proposed annual salary',unit:'AUD',value:120000,stages:[{name:'Shortlist',state:'Shortlisted'},{name:'Evaluate',state:'Interview'},{name:'Offer',state:'Offer approved'}],nodes:[initialNode('trigger','trigger','Candidate shortlisted',0),initialNode('manager','task','Arrange an interview',1,{owner:'HR partner'}),initialNode('rule','condition','Senior salary band?',1,{value:100000}),initialNode('finance','approval','Approve salary exception',1,{owner:'Finance approver'}),initialNode('finish','state','Advance to offer',2,{state:'Offer approved'}),initialNode('email','email','Send offer update',2)]},offboarding:{name:'Employee offboarding',domain:'People',icon:'↗',model:'pb.offboarding.case',desc:'Clear handovers, asset return and a coordinated final day.',event:'Resignation accepted',numeric:'Outstanding asset value',unit:'AUD',value:800,stages:[{name:'Initiate',state:'Open'},{name:'Clearance',state:'In progress'},{name:'Close',state:'Completed'}],nodes:[initialNode('trigger','trigger','Resignation accepted',0),initialNode('manager','task','Complete the handover',1,{owner:'Their manager'}),initialNode('it','task','Collect company assets',1,{owner:'IT team'}),initialNode('hr','approval','HR clearance',1,{owner:'HR partner'}),initialNode('finish','state','Complete offboarding',2,{state:'Completed'}),initialNode('email','email','Confirm final arrangements',2)]},payroll:{name:'Payrun sign-off',domain:'Payroll',icon:'▥',model:'hr.payslip.run',desc:'A controlled path from payroll preparation to authorised release.',event:'Payrun ready for review',numeric:'Total net payroll',unit:'AUD',value:210000,stages:[{name:'Prepare',state:'Draft'},{name:'Check',state:'Under review'},{name:'Authorise',state:'Approved'}],nodes:[initialNode('trigger','trigger','Payrun ready for review',0),initialNode('manager','approval','HR payroll review',1,{owner:'HR partner'}),initialNode('rule','condition','Above release threshold?',1,{value:100000}),initialNode('finance','approval','Finance sign-off',1,{owner:'Finance approver'}),initialNode('finish','state','Authorise the payrun',2),initialNode('email','email','Notify payroll team',2,{recipient:'HR partner'})]}};
const STORE='payobook-workflow-design-v1';
let state={view:'journey',template:'expense',draft:null,selected:'manager',history:[],versions:[],zoom:.8,tab:'compare',sim:{amount:2400,department:'Operations',country:'Australia',manager:'available',access:'allowed',actor:'other',decision:'approve'}};
let persisted={drafts:{},versions:[]};try{const p=JSON.parse(localStorage.getItem(STORE));if(p&&p.drafts&&Array.isArray(p.versions))persisted=p}catch(e){}
function newDraft(key){const t=TEMPLATES[key];return {schema:'payobook.workflow.poc/1',template:key,name:t.name,event:t.event,scope:{company:'Demo company',match:'all',rules:[]},stages:clone(t.stages),nodes:clone(t.nodes),revision:0}}
state.draft=persisted.drafts.expense||newDraft('expense');state.versions=persisted.versions;state.sim.amount=TEMPLATES[state.template].value;
function save(){persisted.drafts[state.template]=clone(state.draft);persisted.versions=state.versions;try{localStorage.setItem(STORE,JSON.stringify(persisted));$('#draft-status').textContent='Draft saved in this browser'}catch(e){$('#draft-status').textContent='Storage unavailable · export to keep changes'}$('#save-status').textContent='Local draft'}
function checkpoint(){state.history.push(clone(state.draft));if(state.history.length>40)state.history.shift()}
function change(fn){checkpoint();fn();state.draft.revision++;save();render()}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function current(){return state.draft.nodes.find(n=>n.id===state.selected)||state.draft.nodes[0]}
function nodes(){return state.draft.nodes}
function conditionText(n){const labels={gt:'is greater than',gte:'is at least',lt:'is less than',eq:'equals',ne:'does not equal'};return `${n.field==='amount'?TEMPLATES[state.template].numeric:n.field==='department'?'Department':'Country'} ${labels[n.op]||'equals'} ${n.value}${n.field==='amount'?' '+TEMPLATES[state.template].unit:''}`}
function detail(n){if(n.type==='trigger')return state.draft.event;if(n.type==='condition')return conditionText(n);if(n.type==='approval')return `${n.owner} · ${n.due} working days`;if(n.type==='email')return `To ${n.recipient.toLowerCase()} · after previous step`;if(n.type==='task')return `Assigned to ${n.owner.toLowerCase()}`;if(n.type==='wait')return `Resume after ${n.hours} hours`;if(n.type==='state')return `Record → ${n.state}`;return 'Connected service · proposed action'}
function chip(n){if(n.type==='approval')return n.delegate?'♧ Cover enabled':'♧ No cover';if(n.type==='condition')return '↳ Otherwise, skip the next step';if(n.type==='email')return '✓ On completion';if(n.type==='state')return '↗ Business action';if(n.type==='trigger')return '◎ Scope checked';if(n.type==='task')return '◷ Await completion';return n.type==='wait'?'◷ Scheduled resume':'⇄ Retry on failure'}
function card(n,graph=false){return `<button class="step ${graph?'graph-node':''} type-${n.type} ${n.id===state.selected?'selected':''}" data-node="${n.id}" ${graph?'':`draggable="${n.type!=='trigger'}"`} aria-label="Configure ${esc(n.title)}"><div class="step-top">${icons(n.type)}<div><div class="step-title">${esc(n.title)}</div><div class="step-subtitle">${TYPES[n.type].name}</div></div><span class="grip">⠿</span></div><div class="step-detail">${esc(detail(n))}</div><span class="step-chip">${esc(chip(n))}</span>${graph?'<span class="port in"></span><span class="port out"></span>':''}</button>`}
function render(){const t=TEMPLATES[state.template];$('#process-title').textContent=state.draft.name;$('#process-subtitle').textContent=`${t.domain} · ${nodes().length} steps · 3 ways to build`;$('#process-icon').textContent=t.icon;$('#trigger-summary').textContent=state.draft.event;$('#scope-summary').textContent=state.draft.scope.rules.length?`${state.draft.scope.rules.length} eligibility filter${state.draft.scope.rules.length>1?'s':''}`:'All departments';$$('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===state.view);b.setAttribute('aria-pressed',String(b.dataset.view===state.view))});$('#palette').innerHTML=Object.entries(TYPES).filter(([k])=>k!=='trigger').map(([k,t])=>`<button class="palette-item" draggable="true" data-block="${k}" aria-label="Add ${t.name}">${icons(k)}${t.name}<small>⠿</small></button>`).join('');const views={journey:['A journey everyone can follow','Drag steps between stages. Select a card to configure it.'],canvas:['Every path, in the picture','Drag nodes to arrange. Conditions create connected alternate paths.'],blueprint:['A shared picture of responsibility','Drag a card to change its stage and responsible team.']};$('#view-title').textContent=views[state.view][0];$('#view-hint').textContent=views[state.view][1];$('#workflow-summary').textContent=`${state.draft.stages.length} stages · ${nodes().filter(n=>n.type==='approval').length} approvals · ${nodes().filter(n=>n.type==='condition').length} decisions · one shared definition`;
if(state.view==='journey')renderJourney();else if(state.view==='canvas')renderCanvas();else renderBlueprint();renderInspector();bindDrag();}
function renderJourney(){$('#workarea').innerHTML=`<div class="journey" style="--stage-count:${state.draft.stages.length}">${state.draft.stages.map((s,i)=>`<div class="stage"><div class="stage-label"><span class="stage-number">0${i+1}</span><strong>${esc(s.name)}</strong><button class="stage-dots" data-action="stage" data-index="${i}" aria-label="Edit ${esc(s.name)} stage">⋯</button></div><div class="stage-state">Record status <b>· ${esc(s.state)}</b></div><div class="stage-cards" data-drop-stage="${i}">${nodes().filter(n=>n.stage===i).map(n=>card(n)).join('')}<button class="drop-add" data-action="add" data-stage="${i}">＋ Add a step</button></div></div>`).join('')}</div>`}
function graphPositions(){const counts={};nodes().forEach((n,i)=>{const row=counts[n.stage]||0;counts[n.stage]=row+1;if(!n.pos)n.pos={x:35+n.stage*320,y:80+row*160}})}
function graphEdges(){const ns=nodes(),edges=[];ns.forEach((n,i)=>{if(!ns[i+1])return;if(n.type==='condition'){edges.push({from:n.id,to:ns[i+1].id,label:'Yes'});if(ns[i+2])edges.push({from:n.id,to:ns[i+2].id,label:'Otherwise'})}else edges.push({from:n.id,to:ns[i+1].id,label:''})});return edges}
function renderCanvas(){graphPositions();const cw=Math.max(1050,state.draft.stages.length*320+30),ch=Math.max(700,...nodes().map(n=>n.pos.y+200));$('#workarea').innerHTML=`<div class="canvas-wrap"><div class="canvas-tools"><button data-action="zoom-out" aria-label="Zoom out">−</button><button data-action="zoom-reset" aria-label="Reset zoom">${Math.round(state.zoom*100)}%</button><button data-action="zoom-in" aria-label="Zoom in">＋</button><button data-action="layout">Auto arrange</button></div><div class="canvas-surface" style="transform:scale(${state.zoom});width:${cw}px;height:${ch}px"><svg style="width:${cw}px;height:${ch}px" class="canvas-svg" aria-label="Workflow connections"></svg>${nodes().map(n=>card(n,true)).join('')}<div class="canvas-caption">Drag a block onto the canvas to add it. Select a decision to change its routing rule.</div></div></div>`;positionGraph();}
function positionGraph(){nodes().forEach(n=>{const el=$(`[data-node="${n.id}"]`);if(el&&n.pos){el.style.left=n.pos.x+'px';el.style.top=n.pos.y+'px'}});drawEdges()}
function drawEdges(){const svg=$('.canvas-svg');if(!svg)return;svg.innerHTML=`<defs><marker id="arrow" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 8 4 L 0 8 z" fill="#b6a7cf"/></marker></defs>`+graphEdges().map(e=>{const a=nodes().find(n=>n.id===e.from),b=nodes().find(n=>n.id===e.to),ae=$(`[data-node="${a.id}"]`),be=$(`[data-node="${b.id}"]`);let x1=a.pos.x+185,y1=a.pos.y+(ae?.offsetHeight||120)/2,x2=b.pos.x,y2=b.pos.y+(be?.offsetHeight||120)/2,path,lx,ly;const sameColumn=Math.abs(a.pos.x-b.pos.x)<80&&b.pos.y>a.pos.y;if(sameColumn){x1=a.pos.x+92.5;y1=a.pos.y+(ae?.offsetHeight||120);x2=b.pos.x+92.5;y2=b.pos.y;const mid=(y1+y2)/2;path=`M${x1},${y1} C${x1},${mid} ${x2},${mid} ${x2},${y2}`;lx=x1+8;ly=mid-8}else{const bend=Math.max(45,Math.abs(x2-x1)/2);path=`M${x1},${y1} C${x1+bend},${y1} ${x2-bend},${y2} ${x2},${y2}`;lx=x1+12;ly=y1-22}return `<path d="${path}" fill="none" stroke="${e.label==='Otherwise'?'#c1b0d4':'#bdb2cd'}" stroke-width="1.6" ${e.label==='Otherwise'?'stroke-dasharray="5 4"':''} marker-end="url(#arrow)"/>${e.label?`<rect x="${lx}" y="${ly}" width="${e.label==='Yes'?29:67}" height="17" rx="4" fill="#fbf8ff"/><text x="${lx+5}" y="${ly+12}" font-size="9" fill="#947ea9">${e.label}</text>`:''}`}).join('')}
function renderBlueprint(){const owners=[...new Set(['Employee',...nodes().filter(n=>!['trigger','state','condition','wait','email','webhook'].includes(n.type)).map(n=>n.owner),'System'])];$('#workarea').innerHTML=`<div class="lane-board"><div class="lane-headers" style="grid-template-columns:105px repeat(${state.draft.stages.length},minmax(145px,1fr))"><div>RESPONSIBILITY</div>${state.draft.stages.map((s,i)=>`<div>0${i+1} &nbsp; ${esc(s.name)}</div>`).join('')}</div>${owners.map(owner=>`<div class="lane-row" style="grid-template-columns:105px repeat(${state.draft.stages.length},minmax(145px,1fr))"><div class="lane-label"><span>◉</span>${esc(owner)}</div>${state.draft.stages.map((s,i)=>`<div class="lane-cell" data-drop-stage="${i}" data-owner="${esc(owner)}">${nodes().filter(n=>n.stage===i&&n.owner===owner).map(n=>`<button class="lane-card ${n.id===state.selected?'selected':''}" data-node="${n.id}" draggable="${n.type!=='trigger'}">${icons(n.type)}<span>${esc(n.title)}<small>${TYPES[n.type].name}</small></span></button>`).join('')}</div>`).join('')}</div>`).join('')}<div class="board-explainer"><b>Ownership, made visible.</b> People do the work; the system handles rules and actions. Moving a human step between rows changes its responsibility. Permissions and delegation are checked separately.</div></div>`}
function renderInspector(){const n=current();if(!n)return;let content=field('Step name',input('title',n.title,'text','data-edit="title" maxlength="70"'));
if(n.type==='trigger')content+=field('When this happens',input('event',state.draft.event,'text','data-edit-event="true"'))+`<button class="button white" data-action="scope">◎ Configure eligibility filters</button><div class="mini-note">One start event per process. Scope selects records; it never grants access to them.</div>`;
if(n.type==='approval'||n.type==='task')content+=field(n.type==='approval'?'Who approves?':'Who does the work?',select('owner',PEOPLE.filter(p=>p!=='System'),n.owner,'data-edit="owner"'),'Resolved from this record’s company and reporting structure.')+field('Due within',input('due',n.due,'number','data-edit="due" min="1" max="90"'),'Working days; calendar comes from the business adapter.')+`<div class="section-label">PEOPLE & COVER</div><label class="check-field"><input type="checkbox" data-edit="delegate" ${n.delegate?'checked':''}>Use valid approval cover if unavailable</label><label class="check-field"><input type="checkbox" data-edit="independent" ${n.independent?'checked':''}>Keep requester and approver different</label><div class="mini-person"><span class="avatar">${n.owner==='Their manager'?'MC':n.owner==='Finance approver'?'JT':'AL'}</span><div><b>${n.owner==='Their manager'?'Maya Chen':n.owner==='Finance approver'?'Jordan Taylor':'Alex Lee'}</b><small>Sample resolution · Operations</small></div></div><div class="mini-note">Routing and access are separate. A delegate must still be eligible to read the record and complete this action.</div>`;
if(n.type==='condition')content+=field('Check this field',select('field',[['amount',TEMPLATES[state.template].numeric],['department','Department'],['country','Country']],n.field,'data-edit="field"'))+field('Condition',select('op',n.field==='amount'?[['gt','Is greater than'],['gte','Is at least'],['lt','Is less than'],['eq','Equals']]:[['eq','Equals'],['ne','Does not equal']],n.op,'data-edit="op"'))+field('Value',input('value',n.value,n.field==='amount'?'number':'text',`data-edit="value" ${n.field==='amount'?'min="0"':''}`))+`<div class="section-label">TWO CLEAR PATHS</div><div class="mini-note"><b>Yes</b> → run the next step.<br><b>Otherwise</b> → skip that step, then rejoin.<br><br>This prototype demonstrates one-step branches. Nested routes and parallel joins are in the implementation plan.</div>`;
if(n.type==='email')content+=field('Send to',select('recipient',PEOPLE.filter(p=>p!=='System'),n.recipient,'data-edit="recipient"'))+field('Message',`<textarea data-edit="body" maxlength="1000">${esc(n.body)}</textarea>`,'Recipient and record tokens would come from the selected process.')+`<div class="mini-note">Sent only after the previous executed step completes. The simulator previews the message; no email is sent.</div>`;
if(n.type==='state')content+=field('Record status after this action',select('state',[...new Set([...state.draft.stages.map(s=>s.state),'Approved','Rejected','Completed',n.state])],n.state,'data-edit="state"'))+`<div class="mini-note">The real integration must call a supported business action. A workflow phase does not create or overwrite a model’s state values.</div>`;
if(n.type==='wait')content+=field('Wait for',input('hours',n.hours,'number','data-edit="hours" min="1" max="720"'),'Hours after the previous step completes.')+`<div class="mini-note">The proposed runtime persists the wake-up time and resumes safely after restarts.</div>`;
if(n.type==='webhook')content+=field('Connected service',select('service',['HR directory','Finance system','Service desk'],n.service||'Service desk','data-edit="service"'))+`<div class="mini-note">Integration catalogue concept. Production requires configured credentials, approved actions, retry policies and idempotency. This POC makes no external calls.</div>`;
if(n.type!=='trigger')content+=`<div class="section-label">PLACE IN THE JOURNEY</div>`+field('Stage',select('stage',state.draft.stages.map((s,i)=>[i,s.name]),n.stage,'data-edit="stage"'))+`<div class="inspector-actions"><button class="button white" data-action="move-up">↑ Earlier</button><button class="button white" data-action="move-down">↓ Later</button><button class="button white danger" data-action="delete">Remove</button></div>`;
$('#inspector').innerHTML=`<div class="panel-heading">STEP SETTINGS</div><div class="inspector-heading">${icons(n.type)}<div><strong>${TYPES[n.type].name}</strong><small>Changes update all three views</small></div></div>${content}`;
}
function addNode(type,stage,position=null){const id='n_'+Date.now().toString(36);change(()=>{const n=initialNode(id,type,TYPES[type].name,Number(stage),position?{pos:position}:{});if(type==='condition')n.value=TEMPLATES[state.template].value/2;let index=nodes().findLastIndex(n=>n.stage<=Number(stage));nodes().splice(index+1,0,n);state.selected=id});toast(`${TYPES[type].name} added. Configure it on the right.`)}
function moveNode(id,stage,before=null,owner=null){const n=nodes().find(n=>n.id===id);if(!n||n.type==='trigger')return;if(owner&&['approval','task'].includes(n.type)&&owner==='System'){toast('Human steps need a person or a team.');return}if(owner&&!['approval','task'].includes(n.type)&&owner!=='System'){toast('Automated actions stay in the System row.');return}change(()=>{let list=nodes().filter(x=>x.id!==id);n.stage=Number(stage);delete n.pos;if(owner&&['approval','task'].includes(n.type))n.owner=owner;let index=before?list.findIndex(x=>x.id===before):list.findLastIndex(x=>x.stage<=n.stage)+1;index=Math.max(1,index);list.splice(index,0,n);state.draft.nodes=list});}
let dragData=null,dragged=false;
function bindDrag(){$$('[draggable="true"]').forEach(el=>{el.addEventListener('dragstart',e=>{dragData=el.dataset.block?{type:el.dataset.block}:{id:el.dataset.node};e.dataTransfer.setData('text/plain',JSON.stringify(dragData));e.dataTransfer.effectAllowed='move'});el.addEventListener('dragend',()=>{dragData=null;$$('.drop-target').forEach(x=>x.classList.remove('drop-target'))})});$$('[data-drop-stage]').forEach(zone=>{zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('drop-target')});zone.addEventListener('dragleave',e=>{if(!zone.contains(e.relatedTarget))zone.classList.remove('drop-target')});zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('drop-target');if(!dragData)return;const before=e.target.closest('[data-node]')?.dataset.node;if(dragData.type)addNode(dragData.type,zone.dataset.dropStage);else if(before!==dragData.id)moveNode(dragData.id,zone.dataset.dropStage,before,zone.dataset.owner);dragData=null})});const canvas=$('.canvas-wrap');if(canvas){canvas.addEventListener('dragover',e=>e.preventDefault());canvas.addEventListener('drop',e=>{e.preventDefault();if(dragData?.type){const r=$('.canvas-surface').getBoundingClientRect();addNode(dragData.type,1,{x:Math.max(0,(e.clientX-r.left)/state.zoom),y:Math.max(60,(e.clientY-r.top)/state.zoom)})}dragData=null});$$('.graph-node').forEach(el=>{el.addEventListener('pointerdown',e=>{if(e.button!==0)return;const n=nodes().find(n=>n.id===el.dataset.node);const sx=e.clientX,sy=e.clientY,origin={...n.pos};let changed=false;el.setPointerCapture(e.pointerId);const move=ev=>{const dx=(ev.clientX-sx)/state.zoom,dy=(ev.clientY-sy)/state.zoom;if(!changed&&Math.abs(dx)+Math.abs(dy)>5){checkpoint();changed=true;dragged=true}if(changed){n.pos={x:Math.max(0,Math.min($('.canvas-surface').offsetWidth-200,origin.x+dx)),y:Math.max(50,Math.min($('.canvas-surface').offsetHeight-140,origin.y+dy))};positionGraph()}};const end=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',end);el.removeEventListener('pointercancel',end);if(changed){save();setTimeout(()=>dragged=false,0)}};el.addEventListener('pointermove',move);el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end)})})}}
function openModal(title,eyebrow,html){$('#modal-title').textContent=title;$('#modal-eyebrow').textContent=eyebrow;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0}
function closeModal(){$('#modal').close()}
function designTabs(active){return `<div class="modal-tabs">${[['compare','Three options'],['architecture','How it connects'],['capabilities','What exists today'],['roadmap','Build plan'],['sources','Research & inspiration']].map(([id,title])=>`<button data-action="${id}" class="${active===id?'selected':''}">${title}</button>`).join('')}</div>`}
function compare(){openModal('Three ways to make work flow','DESIGN RECOMMENDATION',designTabs('compare')+`<p class="lead">Start with the business story. Reveal complexity when it is needed. The three concepts share one definition, so a process never has to be rebuilt to see it another way.</p><div class="compare-grid"><div class="compare-card recommended"><div class="number">01</div><h3>Journey Studio</h3><span class="status-pill">Recommended default</span><p><b>Best for</b> HR teams and process owners. Drag readable cards into familiar stages. Edit people, conditions and actions in context.</p><p><b>Trade-off</b> Less room for dense branching. Complex subflows should collapse into named steps.</p><button class="button primary" data-pick-view="journey">Try Journey Studio →</button></div><div class="compare-card"><div class="number">02</div><h3>Flow Canvas</h3><span class="status-pill proposed">Advanced view</span><p><b>Best for</b> automation specialists. Inspect decision branches and connected actions in one spatial map.</p><p><b>Trade-off</b> Large graphs need grouping, validation, search and navigation. An empty canvas can overwhelm new users.</p><button class="button white" data-pick-view="canvas">Try Flow Canvas →</button></div><div class="compare-card"><div class="number">03</div><h3>Responsibility Blueprint</h3><span class="status-pill proposed">Operational view</span><p><b>Best for</b> HR, Finance and IT handovers. Rows show responsibility; columns show stages. Move work between owners.</p><p><b>Trade-off</b> A lane board alone cannot express every exception. Use the same step inspector and route definition.</p><button class="button white" data-pick-view="blueprint">Try the Blueprint →</button></div></div><div class="recommendation"><strong>My recommendation: ship Journey Studio first, with one runtime and three views.</strong> Make templates, plain-language rules, inline cover checks and “Try an example” the everyday experience. Add Canvas for complex automation and Blueprint for ownership reviews. Preserve constructs that a simpler view cannot edit; never flatten or silently discard them.</div><p class="lead">The next step beyond familiar builders: explain <em>why</em> each record took its route, show whether the assigned person can actually act, replay an example against a draft, and show the impact of a change before publishing it.</p>`)}
function architecture(){openModal('How the pieces become one system','THE CONNECTING MODEL',designTabs('architecture')+`<p class="lead">Workflow Studio coordinates existing business services. It should not become a second source of truth for permissions, payroll or record status.</p><div class="architecture-flow"><div><b>Event + eligible records</b><small>What happened? Which records qualify?</small></div><span>→</span><div><b>Versioned process</b><small>Stages · steps · decisions · people</small></div><span>→</span><div><b>Business actions</b><small>Permission checks · transitions · outbox</small></div><span>→</span><div><b>Explained execution</b><small>History · retries · exceptions · ownership</small></div></div><div class="architecture-grid"><div class="architecture-card"><h3>01 · Stages organise; states govern</h3><p>“Review” is a configurable process phase. “Approved” is a business record status. Entering a phase does not change state automatically. A registered action calls the module’s existing transition and validation.</p></div><div class="architecture-card"><h3>02 · Assignment is separate from access</h3><p>Resolve the manager, responsibility or team first. Then check company boundaries, ACLs, record rules and field policy. Missing permission produces a clear exception; routing never silently broadens access.</p></div><div class="architecture-card"><h3>03 · Cover has two distinct meanings</h3><p>Approval cover substitutes an eligible decision maker for a defined time. Access delegation temporarily lends scoped permissions. Display both together, but keep their policies, expiry and audit trails separate.</p></div><div class="architecture-card"><h3>04 · Domains become readable rule groups</h3><p>Offer approved fields and typed all/any conditions. “Department is Operations” is an eligibility filter. A decision inside a process selects a path. Compile validated rules through the business adapter; never execute arbitrary user code.</p></div><div class="architecture-card"><h3>05 · Completion drives automation</h3><p>Explicit events such as <code>approval.step.completed</code> release the next action. “Email after approval” waits for that event. Persist timers and human tasks; use a transactional outbox, deduplication, retries and visible failure states.</p></div><div class="architecture-card"><h3>06 · One definition, three views</h3><p>A proposed orchestration document contains stable node IDs, typed edges, scope, people policies and optional layout. Published versions are immutable. Each run stays pinned to its version; changes apply to new work unless explicitly migrated.</p></div></div><div class="recommendation"><strong>A practical foundation is already here.</strong> Reuse <code>biz_approval_workflow</code>, <code>pb_approval_config</code> and <code>biz_access</code>. Generalise the automation patterns in <code>pb_hiring</code>. Add an orchestration layer and a capability registry instead of replacing working business logic.</div>`)}
function capabilities(){openModal('Build on what already works','REPOSITORY FINDINGS · 8 NOVEMBER 2026',designTabs('capabilities')+`<table class="detail-table"><thead><tr><th>Capability</th><th>Current foundation</th><th>Needed for Workflow Studio</th></tr></thead><tbody>${[
['Approval routing','biz_approval_workflow: sequential steps, conditional inclusion, joint/any decisions within a step.','General branch/merge and parallel-task semantics belong in a new orchestrator.'],['Versioning & simulation','Immutable JSON revisions, draft preview, coverage scans and pinned requests.','Reuse these policies; add graph-aware validation and full action simulation.'],['People & delegation','Role/manager resolution and time-bounded approval cover; access delegation is a separate service.','Unify the UI and explain both resolution and effective permission.'],['Email after a step','Deduplicated notification outbox. Current notify steps queue during approval step construction.','Add completion-bound events; a reordered notify card is insufficient.'],['Events & automation','pb_hiring has company-scoped event rules, action queues, dry runs and loop limits.','Generalise through process adapters; preserve existing hiring behavior.'],['Stages & states','Each model owns its stage/state representation and business transitions.','Capability catalogue exposes allowed actions. Custom phases map to supported transitions.'],['Advanced orchestration','Existing approvals support joint/any people within one step.','Durable parallel tasks, join policies, subflows, cancellation and compensation are new work.'],['Prototype behavior','Three views, drag/drop, editable cards, filters, example traces, local versions and JSON export work here.','No server execution, live AI, email, production publishing or imported customer data.']].map(r=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table><div class="mini-note">Examples for hiring, leave, payroll and other processes illustrate the design. Live adapter coverage and supported transitions must be audited per process before rollout. POC JSON is a proposed design format, not an import file for the current approval engine.</div>`)}
function roadmap(){openModal('A route from concept to platform','IMPLEMENTATION RECOMMENDATION',designTabs('roadmap')+`<p class="lead">Build a thin vertical slice first: one real process, from the designer to a completed, auditable run. Broaden through adapters once the execution contract is proven.</p><div class="phase-list">${[
['1','Define the shared contract','Inventory existing process adapters, facts, triggers and lawful actions. Define graph schema, stable IDs, event timing, data snapshots, cancellation and error semantics. Acceptance: a workflow means the same thing in all views.'],['2','Ship Journey Studio for one process','Reuse the approval engine and publishing controls. Add stage cards, people/cover inspector, typed rules, a completion-bound email action and trace simulation. Acceptance: one end-to-end expense or leave journey, including rejection, missing approver and denied access.'],['3','Make the runtime durable','Persist run/node state and timers. Add concurrency guards, scoped dedupe keys, retries/backoff, dead-letter repair and loop limits. External effects use at-least-once delivery with idempotent handlers, not an exactly-once promise.'],['4','Broaden the visual language','Add Canvas and Blueprint over the same definition. Introduce reusable subflows, nested conditions, parallel branches and explicit all/any joins. Acceptance: no loss of semantics when switching views.'],['5','Expand process coverage','Register hiring, onboarding, offboarding, attendance, payroll and other modules individually. Test each action through its business adapter. Add template permissions, scoped rollout, effective dates and version migration tooling.'],['6','Add intelligence with control','Natural-language drafting can propose an editable graph. Add change-impact comparison, permission coverage, bottleneck insights and draft replay. AI suggestions must pass the same validation and human publication flow.']].map(r=>`<div class="phase-item"><span>${r[0]}</span><div><h3>${r[1]}</h3><p>${r[2]}</p></div></div>`).join('')}</div><div class="recommendation"><strong>Production publication gate:</strong> validate graph reachability, branch exhaustiveness, type-safe facts, authorised actions, actor coverage, company boundaries and recursion limits. Show an impact diff and affected scope. Leave in-flight runs on their existing revision.</div>`)}
function sources(){openModal('Borrow the patterns. Improve the fit.','PRIMARY-SOURCE RESEARCH',designTabs('sources')+`<p class="lead">These official references informed the interaction patterns. The Payobook recommendation is a design inference from this research and the repository, not a claim that the prototype already implements these products’ capabilities.</p><div class="source-list"><a href="https://darwinbox.com/en-us/innovations/extensibility" target="_blank" rel="noopener noreferrer">Darwinbox · Extensibility Suite ↗<span>Borrow cross-module drag-and-drop automation, reusable recipes and testing before deployment. Extend the experience with Payobook’s own people, access and business-action context.</span></a><a href="https://www.zoho.com/creator/business-blueprint.html" target="_blank" rel="noopener noreferrer">Zoho Creator · Business Blueprint ↗<span>Borrow stages, transitions, responsibility and post-stage actions. Keep configurable process phases distinct from each Payobook model’s authoritative status.</span></a><a href="https://help.zoho.com/portal/en/kb/crm/process-management/blueprint/articles/parallel-and-multiple-transitions-configuration-and-usage" target="_blank" rel="noopener noreferrer">Zoho CRM · Parallel and multiple transitions ↗<span>Borrow grouped activities and explicit completion rules. Recommend durable branch/join semantics and version pinning for ongoing Payobook work.</span></a><a href="https://docs.n8n.io/workflows/executions/debug/" target="_blank" rel="noopener noreferrer">n8n · Debug executions ↗<span>Borrow replaying earlier execution data in an editor. Add a Payobook-specific explanation of filters, delegation, access and lawful state changes.</span></a></div><div class="mini-note">Reviewed 8 November 2026. Competitor capabilities can vary by edition. No copied UI assets or customer data are used in this design.</div>`)}
function templates(){openModal('Start with the work you know','PROCESS TEMPLATE LIBRARY',`<p class="lead">Six illustrative processes, one visual language. Each opens a separate browser-local draft; switching templates preserves your edits.</p><div class="template-grid">${Object.entries(TEMPLATES).map(([k,t])=>`<button class="template-option" data-template="${k}"><span>${t.icon}</span><strong>${t.name}</strong><p>${t.desc}</p><small>${t.domain} &nbsp; →</small></button>`).join('')}</div>`)}
function loadTemplate(key){state.template=key;state.draft=clone(persisted.drafts[key]||newDraft(key));state.selected=state.draft.nodes.find(n=>n.type==='approval'||n.type==='task')?.id||'trigger';state.history=[];state.sim.amount=TEMPLATES[key].value;save();render();closeModal();toast(`${TEMPLATES[key].name} opened`)}
function scope(){const s=state.draft.scope;openModal('Choose when this process applies','TRIGGER & ELIGIBILITY',`<div class="scope-grid"><div>${field('Process name',input('process-name',state.draft.name,'text','maxlength="80"'))}${field('Start event',input('process-event',state.draft.event,'text','maxlength="80"'))}${field('Company boundary',input('company',s.company),'A required scope boundary. Production uses authorised companies from your session.')}<div class="mini-note">Eligibility filters determine which records start this workflow. They do not replace access controls. This POC uses fictional records within Demo company.</div></div><div>${field('Match records where',select('scope-match',[['all','All conditions match'],['any','Any condition matches']],s.match))}<div id="rules">${s.rules.map((r,i)=>ruleRow(r,i)).join('')}</div><button class="button white" data-action="add-rule">＋ Add filter</button><div class="section-label">IN PLAIN LANGUAGE</div><div class="rule-preview" id="rules-preview"></div></div></div><div class="modal-actions"><button class="button white" data-action="close">Cancel</button><button class="button primary" data-action="save-scope">Apply settings</button></div>`);updateRulesPreview()}
function ruleRow(r,i){return `<div class="rule-row">${select('rule-field',[['department','Department'],['country','Country'],['amount',TEMPLATES[state.template].numeric]],r.field)}${select('rule-op',[['eq','equals'],['ne','does not equal'],['gt','is greater than']],r.op)}${input('rule-value',r.value)}<button class="icon-btn danger" data-action="remove-rule" aria-label="Remove filter">×</button></div>`}
function readRules(){return $$('#rules .rule-row').map(r=>({field:r.querySelector('[name=rule-field]').value,op:r.querySelector('[name=rule-op]').value,value:r.querySelector('[name=rule-value]').value.trim()}))}
function updateRulesPreview(){if(!$('#rules-preview'))return;const rules=readRules();$('#rules-preview').textContent=rules.length?rules.map(r=>`${r.field} ${r.op==='eq'?'equals':r.op==='ne'?'does not equal':'is greater than'} ${r.value||'…'}`).join(`\n${$('[name=scope-match]').value==='all'?'AND':'OR'} `):'All records within the selected company are eligible.'}
function matchRule(r,facts){const left=r.field==='amount'?Number(facts.amount):String(facts[r.field]||'').toLowerCase();const right=r.field==='amount'?Number(r.value):String(r.value).toLowerCase();return r.op==='gt'?left>right:r.op==='gte'?left>=right:r.op==='lt'?left<right:r.op==='ne'?left!==right:left===right}
function simulate(){openModal('Try a record. See the whole story.','SIMULATION · FICTIONAL DATA',`<p class="lead">Change the example to see which steps run, who covers a manager, and where missing access stops the process. Approvals and task completions are simulated.</p><div class="simulator"><div class="simulation-settings">${field(TEMPLATES[state.template].numeric+' ('+TEMPLATES[state.template].unit+')',input('amount',state.sim.amount,'number','data-sim="amount" min="0"'))}${field('Department',select('department',['Operations','Finance','Engineering'],state.sim.department,'data-sim="department"'))}${field('Country',select('country',['Australia','Indonesia','New Zealand'],state.sim.country,'data-sim="country"'))}${field('Manager availability',select('manager',[['available','Available'],['away','Away · valid cover'],['expired','Away · cover expired']],state.sim.manager,'data-sim="manager"'))}${field('Assigned person’s access',select('access',[['allowed','Can read and act'],['denied','Cannot access this record']],state.sim.access,'data-sim="access"'))}${field('Actor independence',select('actor',[['other','A different person'],['self','Same person as requester']],state.sim.actor,'data-sim="actor"'))}${field('First approval decision',select('decision',[['approve','Approve'],['reject','Reject']],state.sim.decision,'data-sim="decision"'))}<button class="button primary" data-action="run-simulation">▷ Run again</button><div class="mini-note">Example people: Maya (manager), Alex (cover), Jordan (Finance). Dates and permissions are scenario inputs, not live account checks.</div></div><div id="trace"></div></div>`);runSimulation()}
function simulationResult(){const f=state.sim,s=state.draft.scope,rows=[];const row=(title,text,status='ok')=>rows.push({title,text,status});const matches=s.rules.map(r=>matchRule(r,f));if(matches.length&&!(s.match==='all'?matches.every(Boolean):matches.some(Boolean))){row('Not eligible','This example does not match the process filters. No steps would start.','skip');return {rows,status:'excluded',title:'Record excluded by the eligibility filters.'}}row('Eligible record',`${s.company} · ${f.department} · ${f.country}. ${s.rules.length?'Configured filters matched.':'No additional eligibility filters.'}`);let skip=false,firstApproval=true,blocked=false,finalState=state.draft.stages[0].state;for(let i=0;i<nodes().length;i++){const n=nodes()[i];if(skip){row(n.title,'Skipped by the previous condition.','skip');skip=false;continue}if(n.type==='trigger'){row(n.title,`${state.draft.event} starts this draft’s example run.`);continue}if(n.type==='condition'){const yes=matchRule(n,f);row(n.title,`${conditionText(n)} → ${yes?'Yes: run the next step.':'No: skip the next step and rejoin.'}`);skip=!yes;continue}if(['approval','task'].includes(n.type)){if(f.actor==='self'&&n.independent){row(n.title,'Blocked: the resolved actor is also the requester. An independent person is required.','blocked');blocked=true;break}if(f.access==='denied'){row(n.title,'Blocked: the resolved actor cannot read or act on this record. Routing must not grant access.','blocked');blocked=true;break}if(n.owner==='Their manager'&&f.manager!=='available'){if(!n.delegate||f.manager==='expired'){row(n.title,n.delegate?'Blocked: approval cover has expired. Resolve an eligible approver.':'Blocked: the manager is away and cover is disabled.','blocked');blocked=true;break}row(n.title,`Alex Lee covers Maya Chen. Cover is valid, in scope and has access. ${n.type==='task'?'Task completion':'Approval'} simulated.`)}else row(n.title,`${n.owner==='Their manager'?'Maya Chen':n.owner==='Finance approver'?'Jordan Taylor':'Alex Lee'} · ${n.owner}. Access allowed. ${n.independent?'Independent actor checked. ':''}${n.type==='task'?'Task completion':'Approval'} simulated.`);if(n.type==='approval'&&firstApproval){firstApproval=false;if(f.decision==='reject'){row('Request rejected','The first approver rejected the request. Remaining steps and completion email do not run.','blocked');return {rows,status:'rejected',title:'Rejected · later actions were not executed.'}}}continue}if(n.type==='email'){row(n.title,`Email preview to ${n.recipient}: “${n.body}” Queued after the previous completed step. No email sent.`);continue}if(n.type==='state'){finalState=n.state;row(n.title,`Proposed adapter action → ${n.state}. The live module must validate and perform this transition.`);continue}if(n.type==='wait'){row(n.title,`Simulated time advances by ${n.hours} hours. Production would persist a wake-up time.`);continue}row(n.title,`Proposed ${n.service||'Service desk'} action. No network call; runtime would apply retry and deduplication policies.`)}return {rows,status:blocked?'blocked':'complete',title:blocked?'Run stopped · resolve the highlighted exception.':`Example complete · proposed record status: ${finalState}`}}
function runSimulation(){const errors=validate();if(errors.length){$('#trace').innerHTML=`<div class="trace-result blocked">Fix ${errors.length} definition issue${errors.length>1?'s':''} before simulating.</div>`+errors.map(e=>`<div class="review-error">${esc(e)}</div>`).join('');return}const r=simulationResult();$('#trace').innerHTML=`<div class="trace-result ${['blocked','rejected'].includes(r.status)?'blocked':''}"><b>${esc(r.title)}</b><br>Draft revision ${state.draft.revision} · ${r.rows.length} explained events · sample only</div><div class="trace">${r.rows.map((x,i)=>`<div class="trace-row ${x.status}"><span>${x.status==='blocked'?'!':x.status==='skip'?'−':'✓'}</span><div><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p></div></div>`).join('')}</div>`}
function validate(){let errors=[];if(!state.draft.name.trim()||!state.draft.event.trim())errors.push('Give the process a name and start event.');if(!state.draft.scope.company.trim())errors.push('Choose a company boundary.');if(nodes().filter(n=>n.type==='trigger').length!==1||nodes()[0].type!=='trigger')errors.push('A workflow needs exactly one start event, as its first step.');if(!nodes().some(n=>n.type==='state'))errors.push('Add a business state action to define the completed result.');nodes().forEach((n,i)=>{if(!n.title.trim())errors.push('Every step needs a name.');if(n.type==='condition'&&(!nodes()[i+1]||!nodes()[i+2]||nodes()[i+1].type==='condition'))errors.push(`${n.title}: add one conditional step and a following rejoin step; adjacent decisions need the future nested-route engine.`);if(n.type==='condition'&&n.field==='amount'&&(!Number.isFinite(Number(n.value))||Number(n.value)<0))errors.push(`${n.title}: use a valid nonnegative number.`);if(n.type==='email'&&!n.body.trim())errors.push(`${n.title}: write the email message.`);if(n.type==='wait'&&(!Number.isFinite(Number(n.hours))||Number(n.hours)<1))errors.push(`${n.title}: wait at least one hour.`);if(['approval','task'].includes(n.type)&&(!Number.isFinite(Number(n.due))||Number(n.due)<1))errors.push(`${n.title}: set a positive working-day deadline.`)});for(const r of state.draft.scope.rules){if(!String(r.value).trim())errors.push('Complete every eligibility filter.');if(r.op==='gt'&&r.field!=='amount')errors.push('Greater-than eligibility filters require a numeric field.');if(r.field==='amount'&&!Number.isFinite(Number(r.value)))errors.push('Numeric eligibility filters require a number.')}return errors}
function publish(){const errors=validate();openModal('Review a version before saving','LOCAL VERSION CHECKPOINT',`<p class="lead">Save an immutable snapshot in this browser. This demonstrates the production review flow; it does not publish a live workflow or update Odoo.</p>${errors.length?errors.map(e=>`<div class="review-error">${esc(e)}</div>`).join(''):`<div class="review-success">✓ Prototype structure is valid: start event, defined completion, complete fields and supported simple branches.</div>`}<div class="architecture-grid"><div class="architecture-card"><h3>This snapshot</h3><p>${esc(state.draft.name)}<br>${nodes().length} steps · ${state.draft.stages.length} phases<br>${state.draft.scope.rules.length} eligibility filters · ${esc(state.draft.scope.company)}</p></div><div class="architecture-card"><h3>Production review still required</h3><p>Live permission and people coverage, supported adapter actions, graph validation, scope conflicts, an impact diff and publisher authorisation.</p></div></div>${field('Version note',input('version-note','Workflow design review','text','maxlength="160"'))}<div class="mini-note">In the proposed live system, new work uses the newly published version. In-flight runs remain pinned to their original version.</div><div class="modal-actions"><button class="button white" data-action="simulate">Test an example</button><button class="button primary" data-action="confirm-version" ${errors.length?'disabled':''}>Save local version</button></div>`)}
function history(){const versions=state.versions.filter(v=>v.template===state.template);openModal('Your design checkpoints','LOCAL VERSION HISTORY',`<p class="lead">Snapshots are stored only in this browser. Restoring creates an editable copy; it keeps the saved snapshot intact.</p>${versions.length?versions.slice().reverse().map(v=>`<div class="history-item"><span class="status-pill">v${v.version}</span><div><b>${esc(v.note)}</b><p>${new Date(v.at).toLocaleString()} · ${v.draft.nodes.length} steps</p></div><button class="button white" data-restore="${v.id}">Restore draft</button></div>`).join(''):'<div class="blank">No saved versions yet.<br>Use “Save version” after testing your design.</div>'}<div class="modal-actions"><button class="button white" data-action="reset">Reset this template to its sample</button><button class="button primary" data-action="export">Export draft JSON</button></div>`)}
function people(){openModal('People, cover and permissions','ONE EXPERIENCE · DISTINCT POLICIES',`<p class="lead">Choose a responsibility, not a hard-coded name. The live system resolves people from the record’s company, organisation and effective dates.</p><table class="detail-table"><thead><tr><th>Responsibility</th><th>Example person</th><th>Cover</th><th>Access</th></tr></thead><tbody><tr><td><b>Their manager</b></td><td>Maya Chen</td><td>Alex Lee · time bounded</td><td>Checked for each record</td></tr><tr><td><b>Finance approver</b></td><td>Jordan Taylor</td><td>Finance responsibility backup</td><td>Company and action scope</td></tr><tr><td><b>HR partner</b></td><td>Alex Lee</td><td>HR responsibility backup</td><td>Field restrictions still apply</td></tr></tbody></table><div class="recommendation"><strong>Approval cover is not an access grant.</strong> A person may be the correct substitute and still lack permission to act. Show the reason, route the exception to the owner, and use Access Studio only when a deliberate permission change is needed.</div><div class="modal-actions"><button class="button primary" data-action="simulate">Try the “manager away” scenario →</button></div>`)}
function stageEditor(i){const s=state.draft.stages[i];openModal('Give this phase a clear meaning','JOURNEY STAGE',field('Phase name',input('stage-name',s.name,'text','maxlength="40"'))+field('Illustrative record status',input('stage-status',s.state,'text','maxlength="40"'),'This labels the stage. It does not change a record. The business-action step controls the proposed transition.')+`<div class="modal-actions"><button class="button white danger" data-action="remove-stage" data-index="${i}" ${nodes().some(n=>n.stage===i)||state.draft.stages.length<=2?'disabled':''}>Remove empty phase</button><button class="button white" data-action="add-stage" data-index="${i}">＋ Add a phase after this</button><button class="button primary" data-action="save-stage" data-index="${i}">Apply stage labels</button></div>`)}
function addMenu(stage){openModal('What should happen next?','ADD A STEP',`<div class="template-grid">${Object.entries(TYPES).filter(([k])=>k!=='trigger').map(([k,t])=>`<button class="template-option" data-add-type="${k}" data-stage="${stage}">${icons(k)}<strong>${t.name}</strong><p>${t.description}</p><small>Add to ${esc(state.draft.stages[stage].name)} →</small></button>`).join('')}</div>`)}
function recipe(){openModal('A useful starting point, in seconds','GUIDED RECIPE · NO AI SERVICE CONNECTED',`<p class="lead">Choose the ingredients. The recipe adds a decision, an approval and an update to your current workflow. You can edit every card afterwards.</p>${field('Require an extra approval when the amount exceeds',input('recipe-value',TEMPLATES[state.template].value/2,'number','min="0"'))}${field('Ask this responsibility',select('recipe-owner',PEOPLE.filter(p=>!['System','Employee'].includes(p)),'Finance approver'))}<label class="check-field"><input id="recipe-email" type="checkbox" checked>Notify the employee after completion</label><div class="mini-note">Future natural-language assistance can propose these same editable steps. It must use the same validation and publication controls.</div><div class="modal-actions"><button class="button primary" data-action="apply-recipe">Add recipe to the journey →</button></div>`)}
function exportDraft(){const payload={...clone(state.draft),edges:graphEdges(),prototype_only:true,compatibility:'Design proposal. Not directly importable into the current approval engine.'};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`payobook-${state.template}-workflow.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Workflow design exported as JSON')}
function help(){openModal('Explore the three experiences','QUICK START',`<div class="phase-list">${[['1','Build','Drag a building block into a journey stage, or click it to add. Select a card and edit its title, owner, rules or action. Use Earlier/Later buttons as a keyboard-friendly alternative to dragging.'],['2','See it another way','Switch between Journey, Canvas and Blueprint. Your changes remain. Canvas dragging changes layout; Blueprint dragging changes stage and responsibility.'],['3','Test','Use Test workflow. Try a low amount, a high amount, a manager on leave, expired cover, denied access or a rejection. Read the explanation of each step.'],['4','Keep your design','Save a browser-local version or export JSON. The history icon restores saved versions. Explore templates for six process examples.']].map(r=>`<div class="phase-item"><span>${r[0]}</span><div><h3>${r[1]}</h3><p>${r[2]}</p></div></div>`).join('')}</div><div class="mini-note">Working POC: editing, drag/drop, conditions, filters, simulation, local persistence, version snapshots, undo and export. Proposed production features: durable execution, live permissions, integration catalogue, parallel joins, AI drafting and deployment.</div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){state.view=b.dataset.view;render();return}if(b.dataset.pickView){state.view=b.dataset.pickView;closeModal();render();return}if(b.dataset.template){loadTemplate(b.dataset.template);return}if(b.dataset.node){if(dragged)return;state.selected=b.dataset.node;renderInspector();$$('[data-node]').forEach(el=>el.classList.toggle('selected',el.dataset.node===state.selected));return}if(b.dataset.block){addNode(b.dataset.block,current()?.stage??1);return}if(b.dataset.addType){addNode(b.dataset.addType,Number(b.dataset.stage));closeModal();return}if(b.dataset.restore){const v=state.versions.find(v=>v.id===b.dataset.restore);change(()=>{state.draft=clone(v.draft);state.selected=state.draft.nodes[1]?.id||'trigger'});closeModal();toast('Saved snapshot restored as an editable draft');return}const a=b.dataset.action;if(!a)return;const actions={compare,architecture,capabilities,roadmap,sources,templates,scope,simulate,publish,history,people,recipe,help,export:exportDraft,close:closeModal,studio:()=>{closeModal();$('#process-title').scrollIntoView({behavior:'smooth'})},'run-simulation':runSimulation,'zoom-in':()=>{state.zoom=Math.min(1.4,state.zoom+.1);renderCanvas();bindDrag()},'zoom-out':()=>{state.zoom=Math.max(.4,state.zoom-.1);renderCanvas();bindDrag()},'zoom-reset':()=>{state.zoom=.8;renderCanvas();bindDrag()},layout:()=>change(()=>nodes().forEach(n=>delete n.pos)),undo:()=>{if(!state.history.length){toast('No changes to undo yet');return}state.draft=state.history.pop();if(!nodes().some(n=>n.id===state.selected))state.selected=nodes()[0].id;save();render();toast('Last change undone')},add:()=>addMenu(Number(b.dataset.stage)),stage:()=>stageEditor(Number(b.dataset.index)),'add-stage':()=>{const i=Number(b.dataset.index)+1;change(()=>{state.draft.stages.splice(i,0,{name:'New phase',state:'In progress'});nodes().forEach(n=>{if(n.stage>=i)n.stage++;delete n.pos})});stageEditor(i)},'remove-stage':()=>{const i=Number(b.dataset.index);if(nodes().some(n=>n.stage===i)||state.draft.stages.length<=2)return;change(()=>{state.draft.stages.splice(i,1);nodes().forEach(n=>{if(n.stage>i)n.stage--;delete n.pos})});closeModal()},'save-stage':()=>{const name=$('[name=stage-name]').value.trim(),status=$('[name=stage-status]').value.trim();if(!name||!status){toast('Give the phase and status a name.');return}change(()=>state.draft.stages[Number(b.dataset.index)]={name,state:status});closeModal()},delete:()=>{const n=current();if(n.type==='trigger')return;change(()=>{state.draft.nodes=nodes().filter(x=>x.id!==n.id);state.selected=nodes()[0].id});toast('Step removed · use Undo to bring it back')},'move-up':()=>{const i=nodes().findIndex(n=>n.id===state.selected);if(i<=1){toast('The start event stays first');return}moveNode(state.selected,nodes()[i-1].stage,nodes()[i-1].id)},'move-down':()=>{const i=nodes().findIndex(n=>n.id===state.selected);if(i===nodes().length-1){toast('This is already the final step');return}const next=nodes()[i+1],after=nodes()[i+2];moveNode(state.selected,next.stage,after?.stage===next.stage?after.id:null)},'add-rule':()=>{$('#rules').insertAdjacentHTML('beforeend',ruleRow({field:'department',op:'eq',value:'Operations'}));updateRulesPreview()},'remove-rule':()=>{b.closest('.rule-row').remove();updateRulesPreview()},'save-scope':()=>{const name=$('[name=process-name]').value.trim(),event=$('[name=process-event]').value.trim(),company=$('[name=company]').value.trim(),rules=readRules(),match=$('[name=scope-match]').value;if(!name||!event||!company||rules.some(r=>!r.value)){toast('Complete the process name, event, company and filter values.');return}if(rules.some(r=>r.op==='gt'&&r.field!=='amount'||r.field==='amount'&&!Number.isFinite(Number(r.value)))){toast('Use numeric comparisons only with numeric fields.');return}change(()=>{state.draft.name=name;state.draft.event=event;state.draft.scope={company,rules,match};nodes()[0].title=event});closeModal();toast('Trigger and eligibility updated')},'confirm-version':()=>{if(validate().length)return;const version=state.versions.filter(v=>v.template===state.template).length+1;state.versions.push({id:'v'+Date.now(),template:state.template,version,at:new Date().toISOString(),note:$('[name=version-note]').value.trim()||'Design checkpoint',draft:clone(state.draft)});save();closeModal();$('#save-status').textContent=`v${version} saved locally`;toast(`Version ${version} saved in this browser`)},reset:()=>{change(()=>{state.draft=newDraft(state.template);state.selected='manager'});closeModal();toast('Sample restored. Undo remains available.')},'apply-recipe':()=>{const value=Number($('[name=recipe-value]').value),owner=$('[name=recipe-owner]').value,notify=$('#recipe-email').checked;if(!Number.isFinite(value)||value<0){toast('Enter a nonnegative amount.');return}change(()=>{const id=Date.now().toString(36),index=nodes().findLastIndex(n=>n.stage===1)+1;const added=[initialNode('rule_'+id,'condition','Check the threshold',1,{value}),initialNode('approve_'+id,'approval','Additional approval',1,{owner})];nodes().splice(index,0,...added);if(notify)nodes().push(initialNode('email_'+id,'email','Send a completion update',2));state.selected=added[0].id});closeModal();toast('Recipe added. Test the updated route.')}};if(actions[a])actions[a]()});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.edit){const key=el.dataset.edit,n=current();let value=el.type==='checkbox'?el.checked:el.value;if(['stage','due','hours'].includes(key)||key==='value'&&n.field==='amount')value=Number(value);if(key==='stage'){moveNode(n.id,value);return}change(()=>{n[key]=value;if(key==='field'){n.value=value==='amount'?1000:value==='department'?'Operations':'Australia';n.op=value==='amount'?'gt':'eq'}});return}if(el.dataset.editEvent){change(()=>{state.draft.event=el.value;nodes()[0].title=el.value});return}if(el.dataset.sim){state.sim[el.dataset.sim]=el.dataset.sim==='amount'?Number(el.value):el.value;runSimulation();return}if(el.closest('#rules')||el.name==='scope-match')updateRulesPreview()});
document.addEventListener('input',e=>{if(e.target.closest('#rules'))updateRulesPreview()});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='z'&&!/INPUT|TEXTAREA/.test(e.target.tagName)&&!$('#modal').open){e.preventDefault();$('[data-action=undo]').click()}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
render();
